INSERT INTO `app_releases` (`id`, `platform`, `version_name`, `version_code`, `file_path`, `file_size`, `sha256`, `release_notes`, `min_supported_code`, `is_mandatory`, `is_published`, `download_count`, `created_by`, `created_at`) VALUES
(1, 'android', '1.0.4', 5, 'private/releases/2fef167a-71e2-4acd-89e9-4bda67990bb1.apk', 70656501, '6410361a9c5b49c0a524c88564fe41791d57c3448b56e1cb5974b0b4d0682a5c', 'አዲስ በዚህ ስሪት (1.0.4)፦\n• መዝሙር ሲከፍቱ በቀጥታ ማጫወቻው ይከፈታል — ምስሉን ሲነኩ ግጥሙ ይገለበጣል\n• ግጥሞች ያለ ኢንተርኔት እንዲሰሩ በራስ-ሰር ይቀመጣሉ፤ «አውርድ» አሁን ድምጹን ያወርዳል\n• «ዛሬ የሚጠኑ» መዝሙሮችና ምድቦች በመነሻ ገጹ ላይ ይታያሉ\n• ከፕሮግራም ለመቅረት ፈቃድ መጠየቅ ይችላሉ\n• ፕሮግራም ከመጀመሩ 30 ደቂቃ በፊት ማንቂያ ይደርስዎታል\n• መዝሙር፣ ፕሮግራም ወይም ገጽ ሲያጋሩ በቀጥታ መተግበሪያው ውስጥ የሚከፍት አገናኝ ይላካል\n• በማስታወቂያዎች ላይ ተያያዥ ፋይሎችና አገናኞች\n• ተዛማጅ መዝሙሮች፣ የማጫወቻ መዝጊያ (✕) እና የተሻሻለ የኋላ ቁልፍ\n• የቁልፍ ሰሌዳ ሲከፈት ገጹ የማይሸፈንበት ማስተካከያና ሌሎች ጥገናዎች', 0, 0, 0, 8, 1, '2026-09-26 10:05:08'),
(2, 'android', '1.1.0', 6, 'private/releases/2dc3ea19-04c5-4f8c-a3c4-aef66e766499.apk', 87423822, '29271c332c1de777cbf4de0341c5a67ac4c4b2bb6efaa7af956363d664d3aeb9', NULL, 6, 1, 0, 13, 13, '2026-09-28 08:39:42'),
