INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `lrc`, `description`, `category_id`, `cover_image`, `audio_path`, `audio_mime`, `audio_size`, `audio_duration_sec`, `status`, `is_featured`, `view_count`, `favorite_count`, `download_count`, `content_version`, `published_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`, `youtube_url`, `study_on`) VALUES
(1, '(ናሙና) መዝሙር 1', 'ይህ የናሙና መዝሙር ቁጥር 1 ነው።\nየመጀመሪያ ስንኝ — ለሙከራ የተጻፈ ጽሑፍ።\nየሁለተኛ ስንኝ — ለሙከራ የተጻፈ ጽሑፍ።\n\nአዝማች፦\nየአዝማች መስመር — ለሙከራ።\nየአዝማች መስመር — ለሙከራ።', NULL, 'ለሙከራ የተዘጋጀ የናሙና መዝሙር።', 5, NULL, 'public/audio/mezmurs/dd016f54-7967-4f53-bd74-d13947e22389.opus', 'audio/ogg; codecs=opus', 2326612, NULL, 'archived', 1, 29, 2, 2, 6, '2026-09-23 19:55:22', 2, 1, '2026-09-24 19:55:22', '2026-09-25 20:20:25', '2026-09-25 20:20:25', NULL, NULL),
(2, 'ክርስቶስ ተወለደ', 'ክርስቶስ ተወለደ ክርስቶስ ተጠምቀ ክርስቶስ ተወልደ (፪)\nወለደነ ዳግመ (፪) እም መንፈስ ቅዱስ ወማይ (፪)\n\nክርስቶስ ተወለደ ዕሴይ ክርስቶስ ተጠምቀ በማይ (፪)\nወለደነ ዳግመ እማይ (፬)\n\nትርጉም\nክርስቶስ ከዕሴይ ዘር ከዳዊት ወገን ተወለደ። ክርስቶስ በውኀ ተጠመቀ። ዳግመኛም ከውኀ እና ከመንፈስ ቅዱስ ወለደን።', NULL, NULL, 6, NULL, 'public/audio/mezmurs/fa6ea167-c11c-43e1-8fe8-5aa71311efb2.mp3', 'audio/mpeg', 1304285, NULL, 'published', 0, 23, 1, 2, 8, '2026-09-22 19:55:22', 2, 1, '2026-09-24 19:55:22', '2026-10-08 12:52:33', NULL, NULL, NULL),
(3, 'ዮሐንስኒ ይቤ ርኢክዎ', 'ዮሐንስኒ ይቤ ርኢክዎ ለእግዚአብሔር ዘአጥመቆ በዮርዳኖስ (፪)\n\nባሕርኒ ርእየት ደንገፀት ወጐየት ወዮርዳኖስኒ ገብአ ድኅሬሁ (፪)\n\nትርጉም\nዮሐንስም አለ \" በዮርዳኖስ ያጠመቅሁት እግዚአብሔር ወልድ ኢየሱስ ክርስቶስን ባሕር ዐይታው ደንግጣ ስትሸሽ ዮርዳኖሰም ወደ ኋላው ሲመለስ ዕዩ (ተመልከቱ) \"', NULL, NULL, 7, NULL, 'public/audio/mezmurs/86af3bd7-3fa9-4304-a56a-1798eeceeb15.mp3', 'audio/mpeg', 1217768, NULL, 'published', 1, 50, 1, 11, 8, '2026-09-21 19:55:22', 2, 1, '2026-09-24 19:55:22', '2026-10-09 03:24:00', NULL, NULL, NULL),
(4, 'ሱላማጢስ', 'ርዕስ፡ ተመለሺ\n\nተመለሺ ሱላማጢስ ተመለሺ\nእናይሽ ዘንድ ተመለሺ \nየአባትሽን ቤት አትርሺ\n\nኢሳይያስ ተንብዮልሽ\nፈጣን ደመና ያለሽ\nጌታን በጀርባሽ አዝለሽ\nበግብጽ በረሃ የዞርሽ\nየበረሃው ሙቀት ንዳድ\nየለሊቱ ግርማ ከባድ\nበአራዊቱ ድምጽ ሁካታ\nልብሽ በጭንቅ ሲንገላታ\n\nተመለሺ ሱላማጢስ ተመለሺ\nእናይሽ ዘንድ ተመለሺ \nየአባትሽን ቤት አትርሺ\n\n\nስለ ልጅሽ ተርበሻል ጥማትንም ተጠምተሻል\nድካም መንገድ እንግልቱ\nእንዴት ቻልሽው አዛኝቱ\nየልጅሽን ነፍስ የሻቱ\nጠላቶቹ ስለሞቱ\nመሰደዱ ይበቃሻል\nቅድስት አገር ይሻልሻል\n\nተመለሺ ሱላማጢስ ተመለሺ\nእናይሽ ዘንድ ተመለሺ \nየአባትሽን ቤት አትርሺ\n\n\nበኢትዮጲያም እለፊ\nደብረ ቁስቋም ላይም እረፊ\nለዘላለም ከብረሽ\nበአርያም ንገሺ\n\nተመለሺ ሱላማጢስ ተመለሺ\nእናይሽ ዘንድ ተመለሺ \nየአባትሽን ቤት አትርሺ\n\n\nየበደሌ ሸክም በዝቶ\nብሰደድም ጽድቄ ጠፍቶ\nበይ መልሺኝ ለደጃፍሽ\nበክንዶችሽ እቅፍ አርገሽ\nበአለም ስጓዝ አንቺን ትቼሽ\nከእኔ እርቆ ፍቅር ጣዕምሽ\nበበደሌ በኃጢአቴ ዛሬ እንኳን ብሸሽ\nተመለስ በይኝ እመቤቴ በእናትነትሽ\n\nተመለሺ እመቤቴ ተመለሺ\nበልቤ ኑሪ ተመለሺ \nስለ ኃጢአቴ አትሽሺ\n\n\nለአዳም ተስፋው መድኃኒቱ\nድንግል ማርያም አዛኝቱ\nበኃዘንሽ በስደትሽ\nታጥቦ ይጥራ እድፌ በእንባሽ\nበቃኝ ዛሬስ ተሸነፍኩኝ\nእናቴ ሆይ በይ መልሺኝ\nፍቅር ጣዕምሽ ታትሞብኝ\nዛሬ ድኅነት በአንቺ እንዳገኝ\n\nተመለሺ እመቤቴ ተመለሺ\nበልቤ ኑሪ ተመለሺ\nስለ ኃጢአቴ አትሽሺ\n\nተመለሺ እመቤቴ ተመለሺ\nበልቤ ኑሪ ተመለሺ\nስለ ኃጢአቴ አትሽሺ', NULL, NULL, 21, NULL, 'public/audio/mezmurs/a6531996-a038-4ea3-94f3-8d78d1fb64bf.mp3', 'audio/mpeg', 3701757, NULL, 'published', 0, 83, 1, 6, 13, '2026-09-20 19:55:22', 2, 1, '2026-09-24 19:55:22', '2026-10-08 12:53:04', NULL, NULL, NULL),
